# November 26, 2026: Milwaukee, Wisconsin. Eighteen standing buildings in and near downtown, taken as leads from the
# names in one walk-through video and then each checked in sources opened for this batch: Wikipedia read as raw text
# (and its list of National Register listings in Milwaukee), the Wisconsin Historical Society's Architecture and
# History Inventory records, the Encyclopedia of Milwaukee, SAH Archipedia, Urban Milwaukee, the Department of Veterans
# Affairs' Milwaukee pages, and the pages of the Milwaukee Public Library, the Cathedral of St. John the Evangelist,
# the Institute of Christ the King, Best Place at the Historic Pabst Brewery and the Pfister Hotel. Nothing in an
# entry comes from the video.
from data_b import N
from data_ma import W
def L(t,u): return [t,u]

BATCH={'key':'milwaukee_ijfn','label':'Milwaukee, Wisconsin: breweries, churches and downtown landmarks','added':'2026-11-26 13:32'}

MK_NR=W('National Register of Historic Places listings in Milwaukee')
def AHI(n,label): return L('Wisconsin Historical Society property record: '+label,'https://www.wisconsinhistory.org/Records/Property/HI'+n)
STREET="Seen from the public sidewalk; street parking and paid garages downtown (no particular lot checked)."

PLACES=[
N('pabst-brewery-complex-milwaukee','Pabst Brewery Complex (Best Place)','Milwaukee','wi','industry','standing',43.04553,-87.92349,'site','open','walk','','1844–1997',
  "The brewery Jacob Best and his sons founded in 1844 grew into the Pabst Brewing Company (renamed in 1889), which by 1892 was the largest brewer of lager in the world. Brewing here ended in 1997. The complex was listed on the National Register in 2003 and since 2006 has been rebuilt as offices, flats, a hotel and university rooms.",
  look="A whole district of brick brewery buildings on and around Juneau Avenue. The old corporate office and visitor centre is now Best Place, with a tavern and a statue of Captain Frederick Pabst in its courtyard; the former brewhouse is a hotel with six of the original brew kettles kept in its atrium. Best Place's guided history tour goes through the old reception hall, offices, visitor centre and infirmary.",
  accn="The streets through the complex are public. Best Place (901 West Juneau Avenue) runs ticketed history tours and keeps space for walk-ins; tour times from its own page, which says some are cancelled for private events. The brewhouse hotel is a working hotel. Street parking.",
  links=[W('Pabst Brewery Complex'),L('Best Place: tours','https://www.bestplacemilwaukee.com/tours'),MK_NR],brick='no',hours='History tours Fridays and Saturdays 1 and 3 p.m., and 11 a.m. and 1 p.m. on select dates'),
N('blatz-brewery-complex-milwaukee','Blatz Brewery Complex','Milwaukee','wi','industry','standing',43.04544,-87.90826,'site','view','walk','','1891–1906',
  "What is left of the Valentin Blatz brewery, which brewed here from the 1850s until 1959 and by the 1900s was the city's third-largest. Three stock houses of 1891, 1904 and 1906 are on the National Register; most of the other brewery buildings were pulled down in the late 1970s for a parking lot. The 1890 brewery office next door is listed on its own and is used by the Milwaukee School of Engineering.",
  look="Three tall German Renaissance Revival stock houses with round-arched windows, light trim against dark brick; No. 2 has a two-storey square tower in the middle. No. 3, the oldest, lost its pediments when a floor was added in the 1930s, and its west wall was patched with concrete block after the stock house beside it was torn down. The stock houses are flats and the office is a school building: interior not checked.",
  accn="Private flats and Milwaukee School of Engineering buildings round North Broadway and East Juneau Avenue: look from the street. "+STREET,
  links=[W('Valentin Blatz Brewing Company'),AHI('17134','Blatz Brewery Complex'),MK_NR],brick='?',hours=''),
N('schlitz-brewery-complex-milwaukee','Schlitz Brewery Complex (Schlitz Park)','Milwaukee','wi','industry','standing',43.05103,-87.91390,'site','view','walk','','1886–1981',
  "The home plant of the Joseph Schlitz Brewing Company, which moved here, to Third and Walnut, in 1870 and was at times the largest brewer in the country. Schlitz shut the Milwaukee brewery in 1981. The complex, partly torn down, is on the National Register with buildings from 1886 to 1947.",
  look="The Wisconsin Historical Society's walking tour starts at the two-storey cream-brick office of 1886 on West Galena Street, then the 1890 Romanesque brewhouse one door east, the 1900 stock house at King Drive and Galena (cream brick with a stepped and scrolled gable, the Schlitz trademark and a corner tower with a copper dome), the 1902 bottling plant on North Second Street and the 1896 stable at Second and Walnut, with terracotta horses' heads on its Walnut Street front. The buildings are now offices, a school and a restaurant: interiors not checked.",
  accn="Offices and a school round West Galena Street and King Drive: look from the public streets. "+STREET,
  links=[AHI('16349','Joseph Schlitz Brewing Company Stock and Malt House'),W('Joseph Schlitz Brewing Company'),MK_NR],brick='no',hours=''),
N('basilica-of-st-josaphat-milwaukee','Basilica of St. Josaphat','Milwaukee','wi','worship','standing',43.00246,-87.91913,'exact','open','drive','','1896–1901',
  "A domed Polish church on the south side, designed by Erhard Brielmaier on the model of St. Peter's in Rome and built from 1896 to 1901, largely by the parishioners themselves. Its stone came from the federal building in Chicago, then being torn down: the pastor bought the salvage for $20,000 and it came on 500 railway flatcars. Pope Pius XI made it a minor basilica in 1929; it is on the National Register.",
  look="A massive limestone Beaux-Arts church under a great copper dome. Inside, oil paintings of Bible scenes on the walls and the inner dome, plasterwork in gold leaf and stained glass, finished in 1928 by Conrad Schmitt and Gonippo Raggi; it seats about 2,000. Visitors may come in outside the weekend Masses, and an audio tour is sold in the gift shop.",
  accn="Active Catholic parish at 601 West Lincoln Avenue. The hours below are the basilica's own visit page (thebasilica.org), which could not be opened when this was written; they are taken from what a web search quoted from it, and the parish says the church can close for funerals and special Masses. Street parking.",
  links=[W('Basilica of St. Josaphat'),AHI('27210','Saint Josaphat Basilica'),L('The Basilica of St. Josaphat: visit','https://thebasilica.org/visit'),MK_NR],brick='no',hours='Tours and gift shop Monday to Friday 10 a.m. to 3 p.m., Saturday 9 a.m. to 4:30 p.m. (not during weekend Masses)'),
N('cathedral-st-john-evangelist-milwaukee','Cathedral of St. John the Evangelist','Milwaukee','wi','worship','standing',43.04182,-87.90374,'exact','open','walk','','1847–1852',
  "The cathedral of the Catholic Archdiocese of Milwaukee, begun in 1847 and dedicated in 1852, paid for partly with gifts from Bavaria, Belgium, Mexico and Cuba. The top of the tower was rebuilt in 1893. A fire in January 1935 gutted it, leaving the walls and steeple; it was rebuilt by 1942, and a large remodelling in the early 2000s moved the altar forward and was much argued over.",
  look="The 1840s walls and the tower beside Cathedral Square Park. The stained glass, murals and organ were lost in the 1935 fire, so what is inside dates from the rebuilding and the 2000s remodelling. Anyone may attend Mass.",
  accn="Active cathedral at 812 North Jackson Street, east of Cathedral Square Park. Mass times from the cathedral's own page (from July 1, 2026). "+STREET,
  links=[W('Cathedral of St. John the Evangelist (Milwaukee)'),L('The Cathedral of St. John the Evangelist','https://stjohncathedral.org/'),MK_NR],brick='no',hours='Masses Saturday 5 p.m.; Sunday 8 and 10 a.m. and noon (Spanish)'),
N('st-stanislaus-church-milwaukee','St. Stanislaus Church (Oratory)','Milwaukee','wi','worship','standing',43.01260,-87.91766,'exact','open','walk','','1872–1894',
  "The church of St. Stanislaus parish, founded in 1866 as the first Polish parish in Milwaukee and among the first in the country. The cornerstone was laid in 1872 to a design by Leonard Schmidtner; much of the building went up between 1884 and 1894. It is now an oratory of the Institute of Christ the King, which says the Latin Mass.",
  look="A twin-towered brick church on Mitchell Street whose domes were gilded with gold leaf in the 1960s, when the front entrance was remade with a mosaic of Our Lady of Czestochowa. Inside: the original barrel-vaulted ceiling, fine plasterwork, a marble and bronze altar and stained glass of 1963.",
  accn="Active church at 524 West Historic Mitchell Street. Mass times from the oratory's own page; anyone may attend. "+STREET,
  links=[W('St. Stanislaus Catholic Church (Milwaukee)'),AHI('27246','St. Stanislaus Church'),L('St. Stanislaus Oratory','https://www.institute-christ-king.org/milwaukee-home')],brick='no',hours='Sunday Masses 7:30 and 10 a.m. and noon; Saturday 9 a.m. and 4 p.m.; Friday 6:30 p.m.'),
N('tripoli-shrine-temple-milwaukee','Tripoli Shrine Temple','Milwaukee','wi','civic','standing',43.03931,-87.95177,'exact','view','walk','','1926–1928',
  "A Shriners' temple, not a religious building, built from 1926 to 1928 to a design by Clas and Shepard and opened in May 1928. Its Moorish Revival design is loosely based on the Taj Mahal. It is on the National Register as Tripoli Temple.",
  look="A main dome 30 feet across covered in patterned tile, two smaller domes like it, striped stone coursing in the Spanish Moorish manner and a pair of kneeling camels at the entrance. The interior has floral ceramic tile and plaster lattice work; whether it is open to the public was not checked.",
  accn="At 3000 West Wisconsin Avenue; look from the street. "+STREET,
  links=[W('Tripoli Shrine Temple'),MK_NR],brick='?',hours=''),
N('mayer-boot-shoe-building-milwaukee','Mayer Boot and Shoe Company Building (The Fortress)','Milwaukee','wi','industry','standing',43.05301,-87.91065,'exact','view','walk','','1880–1912',
  "A shoe factory begun in 1880 by Frederick Mayer, a German-born shoe dealer, and rebuilt and enlarged from 1892 to 1912 (Herman Schnetzky's firm, then E. R. Liebert). The firm was organised in 1884 and the factory ran until 1938. The Alexander Company has made it into 132 flats, known as The Fortress.",
  look="A U-shaped brick block up to eight storeys, its middle raised two storeys higher as a tower with a battlemented parapet, round-arched windows at the top and two-storey arched doorways. The state record calls the outside virtually unchanged since 1912.",
  accn="Private flats at 100 East Pleasant Street (once 116 East Walnut Street): look from the street. "+STREET,
  links=[AHI('16744','Mayer Boot and Shoe Company Building'),L('Urban Milwaukee: Mayer Boot and Shoe Company Building','https://urbanmilwaukee.com/building/f-mayer-boot-and-shoe-company-building'),MK_NR],brick='yes',hours=''),
N('central-library-milwaukee','Central Library (Milwaukee Public Library)','Milwaukee','wi','civic','standing',43.03953,-87.92235,'exact','open','walk','','1893–1898',
  "The city's main library, built after an 1893 design competition (74 entries, one from Frank Lloyd Wright) to hold both the public library and the public museum. Ferry and Clas of Milwaukee won with a Neo-Renaissance building a block long; the south front's colonnade may have been inspired by the Louvre. It is a Milwaukee landmark and on the National Register.",
  look="A domed rotunda with mosaic floors laid by Italian craftsmen, yellow Siena marble, scagliola columns, oak and mahogany, and stained-glass light fittings. The library offers free public tours on Saturdays at 11 a.m., starting in the rotunda.",
  accn="Public library at 814 West Wisconsin Avenue; the wheelchair entrance is at 813 West Wells Street. Hours from the library's own page; it says some rooms keep other hours. "+STREET,
  links=[W('Central Library (Milwaukee)'),L('Milwaukee Public Library: Central Library','https://mpl.org/hours_locations/central.php'),MK_NR],brick='no',hours='Monday and Tuesday 10 a.m. to 7 p.m.; Wednesday to Friday 10 a.m. to 6 p.m.; Saturday 9 a.m. to 5 p.m.; Sunday 10 a.m. to 5 p.m.'),
N('federal-building-milwaukee','Federal Building and U.S. Courthouse','Milwaukee','wi','civic','standing',43.03842,-87.90430,'exact','view','walk','','1892–1899',
  "Built from 1892 to 1899 to hold the post office, the federal courts and the customs service under one roof, to a design by Willoughby J. Edbrooke, supervising architect of the Treasury. An addition extended it south in 1929 to 1932. The federal district court is the one original tenant left. It is on the National Register.",
  look="Richardsonian Romanesque in grey granite, filling the block south of Wisconsin Avenue: heavy round arches, a steep hipped roof with gables, and a tall central tower with pinnacles, an arcaded belfry and a pyramid roof. The interiors were restored in 1989 to 1996; interior not checked.",
  accn="A working federal courthouse at 517 East Wisconsin Avenue: look from the street. "+STREET,
  links=[W('Federal Building (Milwaukee, Wisconsin)'),MK_NR],brick='no',hours=''),
N('mitchell-building-milwaukee','Mitchell Building','Milwaukee','wi','civic','standing',43.03727,-87.90858,'exact','view','walk','','1876–1878',
  "A five-storey bank and insurance building put up for Alexander Mitchell, banker and railway president, to a design by E. Townsend Mix; his bank moved in on completion in 1878 and stayed until 1930. It is believed to stand on the site of the house of Solomon Juneau, Milwaukee's founder, and is on the National Register.",
  look="Second Empire: grey Minnesota granite on the ground floor, limestone above, elaborate cornices and window hoods, a mansard roof and an ornate central tower. The outside is highly intact; most of the marble and frescoed interior has been lost to remodelling.",
  accn="Private building at 207 East Michigan Street, next to the Mackie Building: look from the street. "+STREET,
  links=[W('Mitchell Building'),MK_NR],brick='no',hours=''),
N('mackie-building-milwaukee','Mackie Building (Chamber of Commerce)','Milwaukee','wi','civic','standing',43.03717,-87.90808,'exact','view','walk','','1879–1880',
  "Built in 1879 for Alexander Mitchell as the Chamber of Commerce, home of the Milwaukee Grain Exchange, which traded here from 1880 to 1935 when the city was for a time the world's largest primary wheat market. Its trading floor is said to have introduced the octagonal trading pit later copied by exchanges across the country. E. Townsend Mix designed it.",
  look="Five and a half storeys of stone (the state record says Amherst stone; the ground floor is grey granite) with a narrow clock tower 160 feet above the street. Inside, the three-storey Grain Exchange Room with frescoes and gold leaf, restored in the 1980s, with the old pit marked by a plaque in the floor. Since 2016 the upper floors are flats and the room a private hire venue.",
  accn="Private building at 225 East Michigan Street: look from the street. The Grain Exchange Room is a private hire venue. "+STREET,
  links=[W('Mackie Building'),AHI('16295','Mackie Building'),MK_NR],brick='no',hours=''),
N('milwaukee-city-hall','Milwaukee City Hall','Milwaukee','wi','civic','standing',43.04173,-87.90975,'exact','open','walk','','1893–1895',
  "Henry C. Koch's city hall, built from 1893 to 1895 after a design competition, in a Flemish and German Renaissance manner modelled on a German town hall. At 354 feet it had a claim to be the tallest habitable building in the world from 1895 to 1899, and it was Milwaukee's tallest building until 1973. It is a National Historic Landmark.",
  look="Sandstone, St. Louis red pressed brick and terracotta, with a massive entrance tower flanked by four turrets shaped like beer steins. Interior not checked; the City Clerk offers tours (times not checked).",
  accn="Working city hall at 200 East Wells Street. The city's pages on hours and tours could not be opened when this was written; a web search quoting the tour page says tours meet at the information booth in the first-floor rotunda. Hours not checked. "+STREET,
  links=[W('Milwaukee City Hall'),AHI('16297','Milwaukee City Hall'),L('City of Milwaukee: City Hall tours','https://city.milwaukee.gov/cityclerk/Tours'),MK_NR],brick='yes',hours='?'),
N('germania-building-milwaukee','Germania Building','Milwaukee','wi','civic','standing',43.03989,-87.91267,'exact','view','walk','','1896',
  "Built in 1896 for George Brumder's German-language publishing house, to a design by Schnetzky and Liebert; it was then the largest office building in the city. In 1918, amid anti-German feeling, it was renamed the Brumder Building and its three-ton bronze statue of Germania was taken down at night; what became of the statue is not known. The old name came back after a renovation in 1981.",
  look="An eight-storey Classical Revival block with copper domes on its corners shaped like spiked German army helmets. Interior not checked.",
  accn="Private building at 135 West Wells Street: look from the street. "+STREET,
  links=[W('Germania Building'),MK_NR],brick='?',hours=''),
N('pabst-theater-milwaukee','Pabst Theater','Milwaukee','wi','civic','standing',43.04112,-87.91043,'exact','open','walk','','1895',
  "Frederick Pabst bought the Nunnemacher Grand Opera House in 1890; it burned in January 1895, and he had it rebuilt at once to a design by Otto Strack, reopening the same year as the Pabst Theater. It is said to be the fourth-oldest theatre in the United States in continuous use and is a National Historic Landmark.",
  look="German Renaissance Revival outside. Inside, a drum-shaped auditorium with two balconies for about 1,300, reds and maroons with gold and silver, a two-ton Austrian crystal chandelier, a gilded proscenium arch and a 1928 Möller organ. Seen on a show ticket.",
  accn="A working theatre at 144 East Wells Street with about 100 events a year. The theatre group's own page could not be opened when this was written; see its event listings for show times. "+STREET,
  links=[W('Pabst Theater'),MK_NR],brick='?',hours='?'),
N('north-point-water-tower-milwaukee','North Point Water Tower','Milwaukee','wi','water','standing',43.05972,-87.87987,'exact','view','walk','','1873–1874',
  "Built as part of Milwaukee's first public waterworks to a design by Charles A. Gombert and put in service in September 1874. It enclosed a wrought-iron standpipe four feet across and 120 feet tall that took up the shocks from the steam pumps at the North Point pumping station below the bluff, and kept the water from freezing. Electric pumps made it unneeded in 1963.",
  look="A 175-foot Victorian Gothic tower of rock-faced local limestone with dressed trim, on the bluff above Lake Michigan.",
  accn="City waterworks landmark on East North Avenue at the top of the bluff; seen from the street. Whether the inside ever opens was not checked. "+STREET,
  links=[W('North Point Water Tower'),L('Encyclopedia of Milwaukee: North Point Water Tower','https://emke.uwm.edu/entry/north-point-water-tower/'),L('SAH Archipedia: North Point Water Tower','https://sah-archipedia.org/buildings/WI-01-MI159'),MK_NR],brick='no',hours=''),
N('soldiers-home-old-main-milwaukee','Soldiers Home: Old Main','Milwaukee','wi','inst','standing',43.02649,-87.97661,'exact','view','drive','','1867',
  "Old Main, opened in 1867, was one of the first three homes built for disabled Union veterans after the Civil War: the Northwestern Branch of the National Home for Disabled Volunteer Soldiers. E. Townsend Mix designed it in the Gothic Revival style. After years empty it was restored, with five other old buildings on the grounds, and reopened as 101 homes for veterans at risk of homelessness.",
  look="A large Gothic Revival building of Milwaukee's pale Cream City brick with a slate roof. The restoration kept the slate, the original windows and the wood and terrazzo floors. Ward Memorial Theater (1881 to 1882), the chapel and the governor's residence nearby are to be restored next.",
  accn="On the Milwaukee VA Medical Center grounds off General Mitchell Boulevard, at the Soldiers Home historic district; Old Main is veterans' housing and not open to visitors. Whether visitors may walk the grounds was not checked: look from the campus drives.",
  links=[L('VA Milwaukee: Old Main renovation reaps national honors','https://www.va.gov/milwaukee-health-care/stories/old-main-renovation-reaps-national-honors/'),L('VA Milwaukee: three more historic buildings to be renovated','https://www.va.gov/milwaukee-health-care/news-releases/three-historic-buildings-on-milwaukee-va-campus-to-be-renovated-for-service-of-veterans/'),MK_NR],brick='no',hours=''),
N('pfister-hotel-milwaukee','The Pfister Hotel','Milwaukee','wi','hotel','standing',43.03897,-87.90568,'exact','open','walk','','1893',
  "Opened in 1893 for Guido Pfister and his son Charles as the \"Grand Hotel of the West\", to a design by Henry C. Koch, with fireproofing, electricity and thermostats. Ben Marcus bought it in 1962 and added a 23-storey tower behind the old building. The 1986 Register nomination calls it the last 19th-century grand hotel left in downtown Milwaukee.",
  look="Rock-faced Wauwatosa limestone on the first two floors and cream brick above, trimmed with Indiana limestone and terracotta. The main lobby has been restored to look as it first did, and the hotel shows a large collection of Victorian art, with self-guided tours or tours with its artist in residence.",
  accn="A working hotel at 424 East Wisconsin Avenue. "+STREET,
  links=[W('The Pfister Hotel'),L('The Pfister Hotel: about','https://www.thepfisterhotel.com/explore/about/')],brick='no',hours='Hotel open daily; art tours by arrangement with the hotel'),
]

